/**
 * prediction-market-lab — RandomForest inference unit tests.
 *
 * **Parity check** (the gate for):
 * the model-parity-*.json fixtures were generated by running
 * the original.joblib models + hand-crafted feature vectors
 * through `predict_proba`. We load the same JSON model in
 * TS, run the same feature vectors, and assert the output
 * matches the Python output to 1e-9.
 *
 * **Standalone tests** exercise the loader, the walker
 * (leaf and split paths), and the format validation.
 */

import { describe, it, expect } from "vitest";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import {
	loadForestFromJSON,
	RandomForestModel,
	type RandomForestJSON,
} from "../src/strategy/forest";

function readFixture(name: string): string {
	// vitest runs from the repo root, so the relative path is
	// the same as the in-source `?raw` imports.
	return readFileSync(join(process.cwd(), "test", "fixtures", name), "utf8");
}

function readModelArtifact(name: string): string {
	// The model JSONs live in /models at the repo root (NOT in
	// test/fixtures — those are the parity fixtures).
	return readFileSync(join(process.cwd(), "models", name), "utf8");
}

function loadModelFixture(name: string): RandomForestModel {
	const raw = readModelArtifact(name);
	return loadForestFromJSON(raw);
}

describe("RandomForestModel — load + format validation", () => {
	it("loads the weather model and exposes metadata", () => {
		const m = loadModelFixture("reversion-weather-v1.json");
		expect(m.n_features).toBe(20);
		expect(m.n_classes).toBe(2);
	});

	it("loads the actual weather model from the JSON tree", () => {
		const m = loadModelFixture("reversion-weather-v1.json");
		expect(m.n_features).toBe(20);
		expect(m.n_classes).toBe(2);
		expect(m.classes).toEqual([0, 1]);
		expect(m.n_estimators).toBe(200);
		expect(m.max_depth).toBe(6);
		expect(m.trees.length).toBe(200);
		// The model has 20 features; the importances should match.
		expect(m.feature_importances.length).toBe(20);
		// All importances should sum to ~1.
		const sum = m.feature_importances.reduce((a, b) => a + b, 0);
		expect(sum).toBeGreaterThan(0.99);
		expect(sum).toBeLessThan(1.01);
	});

	it("rejects unknown format", () => {
		const bad = {
			version: 1,
			format: "unknown-format",
			n_features: 20,
			n_classes: 2,
			classes: [0, 1],
			n_estimators: 0,
			max_depth: 0,
			feature_importances: [],
			trees: [],
		} as unknown as RandomForestJSON;
		expect(() => new RandomForestModel(bad)).toThrow(/unsupported model format/);
	});

	it("rejects wrong feature count at predict time", () => {
		const m = loadModelFixture("reversion-weather-v1.json");
		expect(() => m.predictProbaOne([0, 0, 0])).toThrow(/features has 3 dims, model expects 20/);
	});
});

describe("RandomForestModel — inference parity with Python", () => {
	it("matches the python predict_proba for the weather model", () => {
		const m = loadModelFixture("reversion-weather-v1.json");
		const parity = JSON.parse(readFixture("model-parity-weather.json")) as {
			cases: Array<{ name: string; features: number[]; expected_proba: number[] }>;
		};
		for (const c of parity.cases) {
			const got = m.predictProbaOne(c.features);
			expect(got.length).toBe(c.expected_proba.length);
			// 1e-9 parity with the Python output.
			for (let i = 0; i < got.length; i++) {
				expect(got[i]).toBeCloseTo(c.expected_proba[i], 9);
			}
		}
	});
});

describe("RandomForestModel — walker correctness", () => {
	it("predictProba returns probabilities that sum to 1", () => {
		const m = loadModelFixture("reversion-weather-v1.json");
		const features = new Array(20).fill(0.5);
		const proba = m.predictProbaOne(features);
		const sum = proba.reduce((a, b) => a + b, 0);
		expect(sum).toBeCloseTo(1.0, 9);
	});

	it("handles all-zero input (the 'no info' baseline)", () => {
		const m = loadModelFixture("reversion-weather-v1.json");
		const proba = m.predictProbaOne(new Array(20).fill(0));
		const sum = proba.reduce((a, b) => a + b, 0);
		expect(sum).toBeCloseTo(1.0, 9);
		// No NaN / Infinity.
		for (const p of proba) {
			expect(Number.isFinite(p)).toBe(true);
		}
	});

	it("batch predict returns the same probabilities as one-by-one", () => {
		const m = loadModelFixture("reversion-weather-v1.json");
		const features = new Array(20).fill(0);
		const single = m.predictProbaOne(features);
		const batch = m.predictProba([features, features]);
		expect(batch[0]).toEqual(single);
		expect(batch[1]).toEqual(single);
	});
});
